import type { MarkupOptions } from '../../src/parser.js';
import type { JsonValue } from '../../src/types.js';

export interface MarkupFixture {
  readonly name: string;
  readonly source: string;
  readonly status: 'complete' | 'incomplete' | 'error';
  readonly code?: string;
  readonly text?: string;
  readonly props?: Record<string, JsonValue>;
  readonly options?: Partial<MarkupOptions>;
}
const complete = (name: string, source: string, expected: Pick<MarkupFixture, 'text' | 'props'> = {}): MarkupFixture => ({ name, source, status: 'complete', ...expected });
const reject = (name: string, source: string, code: string): MarkupFixture => ({ name, source, status: 'error', code });
const unfinished = (name: string, source: string, code: string): MarkupFixture => ({ name, source, status: 'incomplete', code });

